function Write-Utf8([string]$Path,[string]$Text){[IO.File]::WriteAllText($Path,$Text,(New-Object Text.UTF8Encoding($false)))}
function Check([string]$Name,[bool]$Pass,[string]$Proof=''){$script:checks[$Name]=$Pass;if(-not$Pass){$script:failures.Add("$Name :: $Proof")}}
function Native([string]$Exe,[string[]]$Arguments,[string]$Cwd=''){$old=$ErrorActionPreference;$ErrorActionPreference='Continue';try{if($Cwd){Push-Location $Cwd};$o=@(& $Exe @Arguments 2>&1);$c=$LASTEXITCODE}finally{if($Cwd){Pop-Location};$ErrorActionPreference=$old};[pscustomobject]@{ExitCode=$c;Output=($o-join"`n")}}
function Sql($Server,[string]$Text,[switch]$NoHeaders,[switch]$NoDatabase){$a=@('--protocol=TCP','--host=127.0.0.1',"--port=$($Server.Port)",'--user=root','--default-character-set=utf8mb4','--batch','--raw');if($NoHeaders){$a+='--skip-column-names'};if(-not$NoDatabase){$a+='--database=enterprise_platform'};$a+="--execute=$Text";Native $mysql $a}
