function Fingerprint($Server){$queries=@("SELECT CONCAT(table_name,'|',engine,'|',table_collation,'|',IFNULL(table_comment,'')) FROM information_schema.tables WHERE table_schema='enterprise_platform' AND table_type='BASE TABLE' ORDER BY table_name","SELECT CONCAT(table_name,'|',ordinal_position,'|',column_name,'|',column_type,'|',is_nullable,'|',IFNULL(column_default,'<NULL>'),'|',IFNULL(collation_name,'<NULL>'),'|',extra,'|',IFNULL(column_comment,'')) FROM information_schema.columns WHERE table_schema='enterprise_platform' ORDER BY table_name,ordinal_position","SELECT CONCAT(table_name,'|',index_name,'|',non_unique,'|',seq_in_index,'|',IFNULL(column_name,'<NULL>'),'|',IFNULL(expression,'<NULL>')) FROM information_schema.statistics WHERE table_schema='enterprise_platform' ORDER BY table_name,index_name,seq_in_index","SELECT CONCAT(trigger_name,'|',event_manipulation,'|',event_object_table,'|',action_timing,'|',action_statement) FROM information_schema.triggers WHERE trigger_schema='enterprise_platform' ORDER BY trigger_name","SELECT CONCAT(constraint_name,'|',table_name,'|',referenced_table_name,'|',unique_constraint_name,'|',update_rule,'|',delete_rule) FROM information_schema.referential_constraints WHERE constraint_schema='enterprise_platform' ORDER BY table_name,constraint_name","SELECT CONCAT(tc.table_name,'|',tc.constraint_name,'|',cc.check_clause) FROM information_schema.table_constraints tc JOIN information_schema.check_constraints cc ON cc.constraint_schema=tc.constraint_schema AND cc.constraint_name=tc.constraint_name WHERE tc.constraint_schema='enterprise_platform' AND tc.constraint_type='CHECK' ORDER BY tc.table_name,tc.constraint_name");$b=[Text.StringBuilder]::new();foreach($q in $queries){$r=Sql $Server $q -NoHeaders;if($r.ExitCode){throw $r.Output};[void]$b.AppendLine($r.Output)};$path=Join-Path $evidence "$($Server.Name)-schema.txt";Write-Utf8 $path $b.ToString();(Get-FileHash $path -Algorithm SHA256).Hash.ToLowerInvariant()}
